    fn lsmStorageStats(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?LsmStorageStats {
        const self: *ProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        var read_activity = self.beginPreparedRead(table_name, .general);
        defer if (read_activity) |*activity| activity.deinit();
        const group_ids = try table_catalog.resolveGroupsForSpan(alloc, self.catalog, table_name, "", "");
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        var out = LsmStorageStats{
            .maintenance = .{},
            .write = .{},
        };
        for (group_ids) |group_id| {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);
            const identity_namespace = try requireTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);
            var db = try openProvisionedWarmStatusDbForTable(
                alloc,
                path,
                self.visibleRootGeneration(group_id),
                self.backend_runtime,
                identity_namespace,
            );
            defer db.close();

            lsm_backend.Backend.accumulateMaintenanceStats(&out.maintenance, db.snapshotLsmMaintenanceStats());
            lsm_backend.Backend.accumulateWriteStats(&out.write, db.snapshotLsmWriteStats());
            out.maintenance_score = @max(out.maintenance_score, db.lsmMaintenanceScore());
            out.maintenance_debt_hint = @max(out.maintenance_debt_hint, db.lsmMaintenanceDebtHint());
        }
        return out;
    }

    fn observedDynamicFieldCapabilitySets(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        observation: DynamicFieldObservationQuery,
    ) !?[]ObservedDynamicFieldCapabilitySet {
        const self: *ProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        var read_activity = self.beginPreparedRead(table_name, .general);
        defer if (read_activity) |*activity| activity.deinit();
        const group_ids = try table_catalog.resolveGroupsForSpan(alloc, self.catalog, table_name, "", "");
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        var merged = std.ArrayListUnmanaged(ObservedDynamicFieldCapabilitySet).empty;
        errdefer freeObservedDynamicFieldCapabilitySetsFromList(alloc, &merged);

        for (group_ids) |group_id| {
            // Sort/queryability evidence lives in the loaded text-index
            // catalog, which status-only DB handles intentionally omit. Lease
            // only an already-present, generation-matched resident or cached
            // query DB: table status must not map a potentially large index.
            // Query admission handles the temporary miss by running its normal
            // preflight warm-and-retry protocol.
            var owner = (provisionedLocalQueryDbOwnerIfPresent(
                self.resident_db,
                self.cache,
                self.catalog,
                alloc,
                group_id,
                self.visibleRootGeneration(group_id),
                table_name,
                true,
            ) catch |err| switch (err) {
                // ResidentDbRetryRequired is a private in-process retry
                // protocol and is intentionally absent from the runtime error
                // ABI. Translate it before this callback crosses a runtime
                // partition so query admission can perform the normal warm
                // retry while status reads remain best effort.
                error.ResidentDbRetryRequired => return error.StorageReadTemporarilyUnavailable,
                else => return err,
            }) orelse return error.StorageReadTemporarilyUnavailable;
            defer owner.deinit();

            const group_sets = try owner.db().observedDynamicFieldCapabilitySetsAlloc(alloc, observation);
            defer freeObservedDynamicFieldCapabilitySets(alloc, group_sets);
            for (group_sets) |set| try mergeObservedDynamicFieldCapabilitySet(alloc, &merged, set);
        }

        return try merged.toOwnedSlice(alloc);
    }
};

fn freeObservedDynamicFieldCapabilitySets(
    alloc: std.mem.Allocator,
    sets: []ObservedDynamicFieldCapabilitySet,
) void {
    for (sets) |*set| set.deinit(alloc);
    if (sets.len > 0) alloc.free(sets);
}

fn freeObservedDynamicFieldCapabilitySetsFromList(
    alloc: std.mem.Allocator,
    sets: *std.ArrayListUnmanaged(ObservedDynamicFieldCapabilitySet),
) void {
    for (sets.items) |*set| set.deinit(alloc);
    sets.deinit(alloc);
}

fn mergeObservedDynamicFieldCapabilitySet(
    alloc: std.mem.Allocator,
    merged: *std.ArrayListUnmanaged(ObservedDynamicFieldCapabilitySet),
    incoming: ObservedDynamicFieldCapabilitySet,
) !void {
    for (merged.items) |*existing| {
        if (!std.mem.eql(u8, existing.index_name, incoming.index_name)) continue;
        for (incoming.field_capabilities) |capability| {
            if (mergeObservedFieldCapabilityIntoSet(existing.field_capabilities, capability)) continue;
            const cloned = try storage_schema.cloneFieldCapabilityAlloc(alloc, capability);
            const old_len = existing.field_capabilities.len;
            const expanded = alloc.realloc(existing.field_capabilities, old_len + 1) catch |err| {
                storage_schema.freeOwnedFieldCapability(alloc, cloned);
                return err;
            };
            existing.field_capabilities = expanded;
            existing.field_capabilities[old_len] = cloned;
        }
        return;
    }

    {
        var new_set = ObservedDynamicFieldCapabilitySet{
            .index_name = try alloc.dupe(u8, incoming.index_name),
            .field_capabilities = &.{},
        };
        errdefer new_set.deinit(alloc);
        new_set.field_capabilities = try storage_schema.cloneFieldCapabilitiesAlloc(alloc, incoming.field_capabilities);
        try merged.append(alloc, new_set);
    }
}

fn mergeObservedFieldCapabilityIntoSet(
    capabilities: []storage_schema.FieldCapability,
    needle: storage_schema.FieldCapability,
) bool {
    for (capabilities) |*capability| {
        if (!fieldCapabilityAggregationKeyEqual(capability.*, needle)) continue;
        mergeObservedFieldCapability(capability, needle);
        return true;
    }
    return false;
}

fn fieldCapabilityAggregationKeyEqual(left: storage_schema.FieldCapability, right: storage_schema.FieldCapability) bool {
    return optionalStringsEqual(left.name, right.name) and
        optionalStringsEqual(left.field, right.field) and
        optionalStringsEqual(left.path_pattern, right.path_pattern) and
        optionalStringsEqual(left.field_pattern, right.field_pattern) and
        optionalStringsEqual(left.match_mapping_type, right.match_mapping_type) and
        optionalStringsEqual(left.emitted_name, right.emitted_name) and
        optionalStringsEqual(left.document_schema, right.document_schema) and
        left.field_type == right.field_type and
        std.mem.eql(u8, left.provenance, right.provenance) and
        optionalStringsEqual(left.analyzer, right.analyzer);
}

fn mergeObservedFieldCapability(
    existing: *storage_schema.FieldCapability,
    incoming: storage_schema.FieldCapability,
) void {
    existing.searchable = existing.searchable and incoming.searchable;
    existing.filterable = existing.filterable and incoming.filterable;
    existing.aggregatable = existing.aggregatable and incoming.aggregatable;
    existing.doc_values = existing.doc_values and incoming.doc_values;
    existing.sortable = existing.sortable and incoming.sortable;
    existing.doc_value_coverage = storage_schema.conservativeDocValueCoverage(existing.doc_value_coverage, incoming.doc_value_coverage);
    existing.queryability_state = storage_schema.conservativeQueryabilityState(existing.queryability_state, incoming.queryability_state);
    existing.sort_lifecycle_state = storage_schema.conservativeSortLifecycleState(existing.sort_lifecycle_state, incoming.sort_lifecycle_state);
    if (!std.mem.eql(u8, existing.missing_null_policy, incoming.missing_null_policy)) {
        existing.missing_null_policy = "mixed";
    }
    if (!indexSortMembershipEqual(existing.index_sort, incoming.index_sort)) {
        existing.index_sort = null;
    }
}

fn optionalStringsEqual(left: ?[]const u8, right: ?[]const u8) bool {
    if (left == null or right == null) return left == null and right == null;
    return std.mem.eql(u8, left.?, right.?);
}

fn indexSortMembershipEqual(left: ?storage_schema.IndexSortMembership, right: ?storage_schema.IndexSortMembership) bool {
    if (left == null or right == null) return left == null and right == null;
    return left.?.position == right.?.position and left.?.desc == right.?.desc;
}

test "provisioned observed dynamic capability merge is conservative across groups" {
    const alloc = std.testing.allocator;

    var covered = storage_schema.observedDynamicFieldCapability(null, "price", .{
        .field_type = .numeric,
        .do_index = true,
        .doc_values = true,
        .sortable = true,
    });
    covered.doc_value_coverage = "covered";
    covered.queryability_state = "queryable";
    storage_schema.refreshSortLifecycleState(&covered);

    const declared = storage_schema.observedDynamicFieldCapability(null, "price", .{
        .field_type = .numeric,
        .do_index = true,
        .doc_values = true,
        .sortable = true,
    });

    const first_set = ObservedDynamicFieldCapabilitySet{
        .index_name = @constCast("full_text_index_v0"),
        .field_capabilities = @constCast((&[_]storage_schema.FieldCapability{covered})[0..]),
    };
    const second_set = ObservedDynamicFieldCapabilitySet{
        .index_name = @constCast("full_text_index_v0"),
        .field_capabilities = @constCast((&[_]storage_schema.FieldCapability{declared})[0..]),
    };

    var merged = std.ArrayListUnmanaged(ObservedDynamicFieldCapabilitySet).empty;
    defer freeObservedDynamicFieldCapabilitySetsFromList(alloc, &merged);

    try mergeObservedDynamicFieldCapabilitySet(alloc, &merged, first_set);
    try mergeObservedDynamicFieldCapabilitySet(alloc, &merged, second_set);

    try std.testing.expectEqual(@as(usize, 1), merged.items.len);
    try std.testing.expectEqual(@as(usize, 1), merged.items[0].field_capabilities.len);
    const capability = merged.items[0].field_capabilities[0];
    try std.testing.expectEqualStrings("price", capability.field.?);
    try std.testing.expect(capability.sortable);
    try std.testing.expectEqualStrings("observed_declared", capability.doc_value_coverage);
    try std.testing.expectEqualStrings("declared", capability.queryability_state);
}

pub const HostedProvisionedTableReadSource = struct {
    replica_root_dir: []const u8,
    catalog: table_catalog.CatalogSource,
    requester: raft_mod.ReadableLeaseRequester,
    router: table_router.HostedGroupRouter,
    executor: http_common.RequestExecutor,
    internal_service_secret: ?[]const u8 = null,
    internal_service_issuer: ?[]const u8 = null,
    io_impl: ?*std.Io.Threaded = null,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime = null,
    group_visible_root_generation: ?GroupVisibleRootGenerationSource = null,

    pub fn init(
        replica_root_dir: []const u8,
        catalog: table_catalog.CatalogSource,
        requester: raft_mod.ReadableLeaseRequester,
        router: table_router.HostedGroupRouter,
        executor: http_common.RequestExecutor,
    ) HostedProvisionedTableReadSource {
        return .{
            .replica_root_dir = replica_root_dir,
            .catalog = catalog,
            .requester = requester,
            .router = router,
            .executor = executor,
        };
    }

    pub fn withIo(self: *HostedProvisionedTableReadSource, io_impl: *std.Io.Threaded) *HostedProvisionedTableReadSource {
        self.io_impl = io_impl;
        return self;
    }

    pub fn withBackendRuntime(self: *HostedProvisionedTableReadSource, backend_runtime: *db_mod.background_runtime.BackendRuntime) *HostedProvisionedTableReadSource {
        self.backend_runtime = backend_runtime;
        return self;
    }

    pub fn withInternalServiceAuth(
        self: *HostedProvisionedTableReadSource,
        secret: ?[]const u8,
        issuer: ?[]const u8,
    ) *HostedProvisionedTableReadSource {
        self.internal_service_secret = secret;
        self.internal_service_issuer = issuer;
        return self;
    }

    fn internalExecutor(self: *HostedProvisionedTableReadSource) http_common.RequestExecutor {
        return .{ .ptr = self, .vtable = &.{ .execute = executeInternalRequest } };
    }

    fn executeInternalRequest(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        request: http_common.HttpRequest,
    ) anyerror!http_common.HttpResponse {
        const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        var client = http_client.ApiHttpClient.init(alloc, self.executor);
        _ = client.withInternalServiceAuth(self.internal_service_secret, self.internal_service_issuer);
        return client.executeRequest(request);
    }

    pub fn withGroupVisibleRootGeneration(self: *HostedProvisionedTableReadSource, generation_source: ?GroupVisibleRootGenerationSource) *HostedProvisionedTableReadSource {
        self.group_visible_root_generation = generation_source;
        return self;
    }

    fn visibleRootGeneration(self: *const HostedProvisionedTableReadSource, group_id: u64) u64 {
        return if (self.group_visible_root_generation) |generation_source| generation_source.visibleRootGenerationForGroup(group_id) else backend_current_root_generation;
    }

    pub fn source(self: *HostedProvisionedTableReadSource) TableReadSource {
        return .{
            .ptr = self,
            .vtable = &.{
                .lookup = lookup,
                .scan = scan,
                .query = query,
                .preflight_query = preflightQuery,
                .preflight_query_group_local = preflightQueryGroupLocal,
                .lookup_group_local = lookupGroupLocal,
                .scan_group_local = scanGroupLocal,
                .query_group_local = queryGroupLocal,
                .search_result_group_local = searchResultGroupLocal,
                .text_stats_group_local = textStatsGroupLocal,
                .algebraic_partials_group_local = algebraicPartialsGroupLocal,
                .join_partition_group_local_with_timeout = joinPartitionGroupLocal,
                .join_rows_group_local_with_timeout = joinRowsGroupLocal,
                .join_unmatched_group_local_with_timeout = joinUnmatchedGroupLocal,
                .join_finalize_group_local_with_timeout = joinFinalizeGroupLocal,
                .join_job_state_group_local = joinJobStateGroupLocal,
                .graph_expand_group_local = graphExpandGroupLocal,
                .graph_hydrate_group_local = graphHydrateGroupLocal,
                .graph_edges_group_local = graphEdgesGroupLocal,
                .local_runtime_statuses = localRuntimeStatuses,
                .document_artifact_manifest = documentArtifactManifest,
                .document_artifact_manifests = documentArtifactManifests,
                .document_artifact_manifest_group_local = documentArtifactManifestGroupLocal,
                .document_artifact_manifests_group_local = documentArtifactManifestsGroupLocal,
            },
        };
    }

    fn lookup(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        key: []const u8,
        opts: db_mod.types.LookupOptions,
        consistency: raft_mod.ReadConsistency,
    ) !?LookupResponse {
        const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        try checkLookupOptionsActive(opts);
        const group_id = (try table_catalog.resolveGroupForKey(alloc, self.catalog, table_name, key)) orelse {
            return null;
        };
        try checkLookupOptionsActive(opts);
        var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse {
            return null;
        };
        defer route.deinit(alloc);
        try checkLookupOptionsActive(opts);

        if (try lookupViaRoute(self, alloc, route, group_id, table_name, key, opts, consistency)) |result| return result;
        return try lookupAcrossActivePlacements(self, alloc, group_id, table_name, key, opts, consistency, route);
    }

    fn documentArtifactManifest(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        doc_key: []const u8,
        artifact_name: []const u8,
        consistency: raft_mod.ReadConsistency,
    ) !?db_mod.types.DocumentArtifactManifest {
        const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        const group_id = (try table_catalog.resolveGroupForKey(alloc, self.catalog, table_name, doc_key)) orelse return null;
        return try documentArtifactManifestHostedRoute(self, alloc, group_id, table_name, doc_key, artifact_name, consistency);
    }

    fn documentArtifactManifests(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        doc_key: []const u8,
        consistency: raft_mod.ReadConsistency,
    ) !?db_mod.types.DocumentArtifactManifestList {
        const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        const group_id = (try table_catalog.resolveGroupForKey(alloc, self.catalog, table_name, doc_key)) orelse return null;
        return try documentArtifactManifestsHostedRoute(self, alloc, group_id, table_name, doc_key, consistency);
    }

    fn documentArtifactManifestHostedRoute(
        self: *HostedProvisionedTableReadSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        doc_key: []const u8,
        artifact_name: []const u8,
        consistency: raft_mod.ReadConsistency,
    ) !?db_mod.types.DocumentArtifactManifest {
        var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse return null;
        defer route.deinit(alloc);
        return switch (route) {
            .local => try documentArtifactManifestProvisionedHostedLocal(null, null, self.replica_root_dir, self.catalog, self.requester, alloc, group_id, self.visibleRootGeneration(group_id), self.backend_runtime, table_name, doc_key, artifact_name, consistency, false),
            .remote => |remote| documentArtifactManifestRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, doc_key, artifact_name) catch |err| switch (err) {
                error.UnexpectedHttpStatus, error.NotFound => null,
                else => err,
            },
        };
    }

    fn documentArtifactManifestsHostedRoute(
        self: *HostedProvisionedTableReadSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        doc_key: []const u8,
        consistency: raft_mod.ReadConsistency,
    ) !?db_mod.types.DocumentArtifactManifestList {
        var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse return null;
        defer route.deinit(alloc);
        return switch (route) {
            .local => try documentArtifactManifestsProvisionedHostedLocal(null, null, self.replica_root_dir, self.catalog, self.requester, alloc, group_id, self.visibleRootGeneration(group_id), self.backend_runtime, table_name, doc_key, consistency, false),
            .remote => |remote| documentArtifactManifestsRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, doc_key) catch |err| switch (err) {
                error.UnexpectedHttpStatus, error.NotFound => null,
                else => err,
            },
        };
    }

    fn lookupViaRoute(
        self: *HostedProvisionedTableReadSource,
        alloc: std.mem.Allocator,
        route: table_router.GroupRoute,
        group_id: u64,
        table_name: []const u8,
        key: []const u8,
        opts: db_mod.types.LookupOptions,
        consistency: raft_mod.ReadConsistency,
    ) !?LookupResponse {
        return switch (route) {
            .local => try lookupProvisionedHostedLocal(null, null, self.replica_root_dir, self.catalog, self.requester, alloc, group_id, self.visibleRootGeneration(group_id), self.backend_runtime, table_name, key, opts, consistency),
            .remote => |remote| lookupRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, key, opts, consistency) catch |err| switch (err) {
                error.UnexpectedHttpStatus => null,
                else => err,
            },
        };
    }

    fn lookupAcrossActivePlacements(
        self: *HostedProvisionedTableReadSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        key: []const u8,
        opts: db_mod.types.LookupOptions,
        consistency: raft_mod.ReadConsistency,
        initial_route: table_router.GroupRoute,
    ) !?LookupResponse {
        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);
        const placements = try metadata_admin.listGroupPlacement(alloc, &snapshot, group_id);
        defer metadata_admin.freePlacementRefs(alloc, placements);

        const local_node_id = self.router.localNodeId();
        const tried_local = initial_route == .local;
        const tried_remote_node_id = switch (initial_route) {
            .remote => |remote| remote.node_id,
            else => 0,
        };

        for (placements) |intent| {
            if (!placementRefReadableWithPeers(placements, intent)) continue;
            const node_id = intent.record.local_node_id;
            if (node_id == local_node_id) {
                if (tried_local or self.router.localStatus(group_id) != .active) continue;
                if (try lookupProvisionedHostedLocal(null, null, self.replica_root_dir, self.catalog, self.requester, alloc, group_id, self.visibleRootGeneration(group_id), self.backend_runtime, table_name, key, opts, consistency)) |result| return result;
                continue;
            }
            if (node_id == tried_remote_node_id) continue;
            if (self.router.nodeStatus(node_id, group_id)) |status| {
                if (status != .active) continue;
            }
            const base_uri = (try self.router.nodeBaseUriForGroup(alloc, group_id, node_id)) orelse continue;
            defer alloc.free(base_uri);
            if (lookupRemote(self.internalExecutor(), alloc, base_uri, group_id, table_name, key, opts, consistency)) |result| {
                return result;
            } else |err| switch (err) {
                error.UnexpectedHttpStatus => continue,
                else => return err,
            }
        }
        return null;
    }

    fn placementRefReadableWithPeers(
        placements: []const *const raft_reconciler.PlacementIntent,
        intent: *const raft_reconciler.PlacementIntent,
    ) bool {
        switch (intent.serving_state) {
            .serving => return true,
            .draining => {
                for (placements) |peer| {
                    if (peer.record.group_id == intent.record.group_id and
                        peer.record.local_node_id != intent.record.local_node_id and
                        peer.serving_state == .serving)
                    {
                        return false;
                    }
                }
                return true;
            },
            .planned, .bootstrapping, .replaying, .cutover_ready, .retiring => return false,
        }
    }

    fn scan(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        from_key: []const u8,
        to_key: []const u8,
        opts: db_mod.types.ScanOptions,
        consistency: raft_mod.ReadConsistency,
    ) !?ScanResponse {
        const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        const group_ids = try table_catalog.resolveGroupsForSpan(alloc, self.catalog, table_name, from_key, to_key);
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;
        try tableReadsValidateDocIdentityReadyForMultiGroup(alloc, self.catalog, table_name, group_ids.len);

        var out = std.ArrayListUnmanaged(u8).empty;
        defer out.deinit(alloc);
        var emitted: u32 = 0;

        for (group_ids) |group_id| {
            var group_opts = opts;
            if (opts.limit > 0) {
                if (emitted >= opts.limit) break;
                group_opts.limit = opts.limit - emitted;
            }

            var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse return null;
            defer route.deinit(alloc);

            var result = switch (route) {
                .local => try scanProvisionedHostedLocal(null, null, self.replica_root_dir, self.catalog, self.requester, alloc, group_id, self.visibleRootGeneration(group_id), self.backend_runtime, table_name, from_key, to_key, group_opts, consistency, false),
                .remote => |remote| try scanRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, from_key, to_key, group_opts),
            } orelse return null;
            defer result.deinit(alloc);

            try out.appendSlice(alloc, result.ndjson);
            emitted += @intCast(std.mem.count(u8, result.ndjson, "\n"));
        }
        return .{ .ndjson = try out.toOwnedSlice(alloc) };
    }

    fn query(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.SearchRequest,
        consistency: raft_mod.ReadConsistency,
    ) !?query_api.QueryResponse {
        const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        try checkQueryDeadline(req);
        const group_ids = try table_catalog.resolveGroupsForSpan(alloc, self.catalog, table_name, "", "");
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;
        try tableReadsValidateDocIdentityReadyForMultiGroup(alloc, self.catalog, table_name, group_ids.len);
        const start_ns = platform_time.monotonicNs();
        if (group_ids.len == 1 and !distributed_graph.supportsCrossRange(req)) {
            var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_ids[0], routePolicyForConsistency(consistency))) orelse return null;
            defer route.deinit(alloc);

            if (route == .local) {
                var execution = try queryHostedLocalDetailed(null, null, self.replica_root_dir, self.catalog, self.requester, alloc, group_ids[0], self.visibleRootGeneration(group_ids[0]), .{ .backend_runtime = self.backend_runtime }, table_name, req, consistency);
                defer execution.releaseDb();
                try checkQueryDeadline(execution.request);
                var result = execution.result;
                defer result.deinit();
                const response_req = execution.request;
                var meta: query_api.QueryResponseMeta = .{
                    .took_ms = @intCast(@divTrunc(platform_time.monotonicNs() - start_ns, std.time.ns_per_ms)),
                    .shard_count = 1,
                    .dense_search = execution.dense_profile,
                };
                defer meta.deinit(alloc);
                try applyHostedProvisionedQueryAggregations(self, alloc, group_ids, table_name, response_req, &result, &meta, execution.db(), consistency);
                execution.releaseDb();
                try checkQueryDeadline(response_req);
                try applyQueryPostProcessing(alloc, response_req, &result, &meta, null, null);
                return try query_api.encodeQueryResponses(alloc, table_name, response_req, meta, result);
            }
        }

        if (requiresDistributedGraphCoordinator(group_ids.len, req)) {
            var base_req = req;
            base_req.graph_queries = &.{};
            base_req.expand_strategy = null;
            var merged = try queryHostedAcrossGroups(self, alloc, group_ids, base_req, table_name, consistency);
            try checkQueryDeadline(base_req);
            defer merged.deinit();
            const graph_req = requestWithResultIdentityGeneration(req, merged);

            const worker = hostedGraphWorker(self);
            const graph_results = try distributed_graph.executeCrossRange(alloc, self.catalog, worker, table_name, graph_req, merged, consistency);
            merged.graph_results = graph_results;

            var meta: query_api.QueryResponseMeta = .{
                .took_ms = @intCast(@divTrunc(platform_time.monotonicNs() - start_ns, std.time.ns_per_ms)),
                .shard_count = @intCast(group_ids.len),
                .merged = true,
            };
            defer meta.deinit(alloc);
            try applyHostedProvisionedQueryAggregations(self, alloc, group_ids, table_name, graph_req, &merged, &meta, null, consistency);
            try checkQueryDeadline(graph_req);
            try applyQueryPostProcessing(alloc, graph_req, &merged, &meta, null, null);
            return try query_api.encodeQueryResponses(alloc, table_name, graph_req, meta, merged);
        }
        var merged = try queryHostedAcrossGroups(self, alloc, group_ids, req, table_name, consistency);
        try checkQueryDeadline(req);
        defer merged.deinit();
        var meta: query_api.QueryResponseMeta = .{
            .took_ms = @intCast(@divTrunc(platform_time.monotonicNs() - start_ns, std.time.ns_per_ms)),
            .shard_count = @intCast(group_ids.len),
            .merged = group_ids.len > 1,
        };
        defer meta.deinit(alloc);
        try applyHostedProvisionedQueryAggregations(self, alloc, group_ids, table_name, req, &merged, &meta, null, consistency);
        try checkQueryDeadline(req);
        try applyQueryPostProcessing(alloc, req, &merged, &meta, null, null);
        return try query_api.encodeQueryResponses(alloc, table_name, req, meta, merged);
    }

    fn preflightQuery(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.SearchRequest,
        consistency: raft_mod.ReadConsistency,
        max_work: u32,
    ) !?db_mod.RuntimePreflightSummary {
        const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
        const group_ids = try table_catalog.resolveGroupsForSpan(alloc, self.catalog, table_name, "", "");
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;
        try tableReadsValidateDocIdentityReadyForMultiGroup(alloc, self.catalog, table_name, group_ids.len);
        try validateResolvedDocFilterForGroups(alloc, self.catalog, table_name, group_ids, req);
        const plan = planFanout(.preflight, self.io_impl, group_ids.len);
        recordFanoutPlan(.preflight, plan);
        if (plan.parallel) {
            return try preflightHostedGroupsParallel(self, alloc, self.io_impl.?.io(), plan.width, group_ids, table_name, req, consistency, max_work);
        }
        if (plan.reason == .no_io and group_ids.len > 1) recordParallelFanoutFallback(.preflight);

        var first_summary: ?db_mod.RuntimePreflightSummary = null;
        var keep_summary = false;
        defer if (!keep_summary) {
            if (first_summary) |*summary| summary.deinit(alloc);
        };
        for (group_ids) |group_id| {
            var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse {
                return null;
            };
            defer route.deinit(alloc);
            switch (route) {
                .local => {
                    const summary = try preflightHostedLocal(null, null, self.replica_root_dir, self.catalog, self.requester, alloc, group_id, self.visibleRootGeneration(group_id), self.backend_runtime, table_name, req, consistency, max_work, false);
                    if (first_summary == null) {
                        first_summary = summary;
                    } else {
                        try mergeRuntimePreflightSummary(alloc, &first_summary.?, summary);
                    }
                },
                .remote => |remote| {
                    const summary = try preflightRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, req, max_work);
                    if (first_summary == null) {
                        first_summary = summary;
                    } else {
                        try mergeRuntimePreflightSummary(alloc, &first_summary.?, summary);
                    }
                },
            }
        }
        keep_summary = true;
        return first_summary;
    }

