fn queryProvisionedAcrossGroups(
    self: *ProvisionedTableReadSource,
    alloc: std.mem.Allocator,
    group_ids: []const u64,
    req: db_mod.types.SearchRequest,
    table_name: []const u8,
    consistency: raft_mod.ReadConsistency,
) !db_mod.types.SearchResult {
    return try queryProvisionedAcrossGroupsAtGenerations(self, alloc, group_ids, req, table_name, consistency, null);
}

fn queryProvisionedAcrossGroupsAtGenerations(
    self: *ProvisionedTableReadSource,
    alloc: std.mem.Allocator,
    group_ids: []const u64,
    req: db_mod.types.SearchRequest,
    table_name: []const u8,
    consistency: raft_mod.ReadConsistency,
    required_identity_generations: ?[]const ?u64,
) !db_mod.types.SearchResult {
    if (!db_mod.types.canonicalHierarchyExecutionWithinBudget(req)) return error.InvalidQueryRequest;
    try tableReadsValidateDocIdentityReadyForMultiGroup(alloc, self.catalog, table_name, group_ids.len);
    try validateResolvedDocFilterForGroups(alloc, self.catalog, table_name, group_ids, req);
    const distributed_text_stats = try collectProvisionedSearchRequestTextStats(self, alloc, group_ids, req, table_name, required_identity_generations);
    defer distributed_stats_mod.deinitTextFieldStats(alloc, distributed_text_stats);
    const selected_generations = try alloc.alloc(?u64, group_ids.len);
    defer alloc.free(selected_generations);
    @memset(selected_generations, null);
    var selected = try queryProvisionedAcrossGroupsPhase(self, alloc, group_ids, req, table_name, consistency, distributed_text_stats, false, required_identity_generations, selected_generations);
    errdefer selected.deinit();
    if (req.hierarchy_children != null) {
        if (req.include_stored) try hydrateProvisionedHierarchyNavigationHits(self, alloc, table_name, req, &selected, consistency);
        return selected;
    }
    if (!req.hierarchy_grouped_matches or selected.hits.len == 0) {
        try hydrateDistributedGroupedUnitHits(
            ProvisionedTableReadSource,
            self,
            alloc,
            table_name,
            req,
            &selected,
            consistency,
        );
        return selected;
    }

    const expansion = try canonicalGroupedMatchExpansionPlanAlloc(alloc, req, selected);
    defer alloc.free(expansion.parent_ids);
    defer if (expansion.filter_json) |value| alloc.free(value);
    const expanded_generations = try alloc.alloc(?u64, group_ids.len);
    defer alloc.free(expanded_generations);
    @memset(expanded_generations, null);
    var expanded = try queryProvisionedAcrossGroupsPhase(self, alloc, group_ids, expansion.request, table_name, consistency, distributed_text_stats, true, selected_generations, expanded_generations);
    defer expanded.deinit();
    try applyCanonicalGroupedMatchExpansion(alloc, &selected, &expanded);
    try hydrateDistributedGroupedUnitHits(
        ProvisionedTableReadSource,
        self,
        alloc,
        table_name,
        req,
        &selected,
        consistency,
    );
    return selected;
}

fn queryHostedAcrossGroups(
    self: *HostedProvisionedTableReadSource,
    alloc: std.mem.Allocator,
    group_ids: []const u64,
    req: db_mod.types.SearchRequest,
    table_name: []const u8,
    consistency: raft_mod.ReadConsistency,
) !db_mod.types.SearchResult {
    return try queryHostedAcrossGroupsAtGenerations(self, alloc, group_ids, req, table_name, consistency, null);
}

fn queryHostedAcrossGroupsAtGenerations(
    self: *HostedProvisionedTableReadSource,
    alloc: std.mem.Allocator,
    group_ids: []const u64,
    req: db_mod.types.SearchRequest,
    table_name: []const u8,
    consistency: raft_mod.ReadConsistency,
    required_identity_generations: ?[]const ?u64,
) !db_mod.types.SearchResult {
    if (!db_mod.types.canonicalHierarchyExecutionWithinBudget(req)) return error.InvalidQueryRequest;
    try tableReadsValidateDocIdentityReadyForMultiGroup(alloc, self.catalog, table_name, group_ids.len);
    try validateResolvedDocFilterForGroups(alloc, self.catalog, table_name, group_ids, req);
    try rejectHostedRemoteResolvedDocFilter(self, alloc, group_ids, table_name, req, consistency);
    const distributed_text_stats = try collectHostedSearchRequestTextStats(self, alloc, group_ids, req, table_name, consistency, required_identity_generations);
    defer distributed_stats_mod.deinitTextFieldStats(alloc, distributed_text_stats);
    const selected_generations = try alloc.alloc(?u64, group_ids.len);
    defer alloc.free(selected_generations);
    @memset(selected_generations, null);
    var selected = try queryHostedAcrossGroupsPhase(self, alloc, group_ids, req, table_name, consistency, distributed_text_stats, false, required_identity_generations, selected_generations);
    errdefer selected.deinit();
    if (req.hierarchy_children != null) {
        if (req.include_stored) try hydrateHostedHierarchyNavigationHits(self, alloc, table_name, req, &selected, consistency);
        return selected;
    }
    if (!req.hierarchy_grouped_matches or selected.hits.len == 0) {
        try hydrateDistributedGroupedUnitHits(
            HostedProvisionedTableReadSource,
            self,
            alloc,
            table_name,
            req,
            &selected,
            consistency,
        );
        return selected;
    }

    const expansion = try canonicalGroupedMatchExpansionPlanAlloc(alloc, req, selected);
    defer alloc.free(expansion.parent_ids);
    defer if (expansion.filter_json) |value| alloc.free(value);
    const expanded_generations = try alloc.alloc(?u64, group_ids.len);
    defer alloc.free(expanded_generations);
    @memset(expanded_generations, null);
    var expanded = try queryHostedAcrossGroupsPhase(self, alloc, group_ids, expansion.request, table_name, consistency, distributed_text_stats, true, selected_generations, expanded_generations);
    defer expanded.deinit();
    try applyCanonicalGroupedMatchExpansion(alloc, &selected, &expanded);
    try hydrateDistributedGroupedUnitHits(
        HostedProvisionedTableReadSource,
        self,
        alloc,
        table_name,
        req,
        &selected,
        consistency,
    );
    return selected;
}

fn queryProvisionedAcrossGroupsPhase(
    self: *ProvisionedTableReadSource,
    alloc: std.mem.Allocator,
    group_ids: []const u64,
    req: db_mod.types.SearchRequest,
    table_name: []const u8,
    consistency: raft_mod.ReadConsistency,
    distributed_text_stats: []const distributed_stats_mod.TextFieldStats,
    expand_selected_groups: bool,
    required_identity_generations: ?[]const ?u64,
    result_identity_generations: []?u64,
) !db_mod.types.SearchResult {
    try validateDistributedPhaseIdentityGenerations(group_ids.len, required_identity_generations, result_identity_generations);
    const shard_req = distributedSearchShardRequest(req, distributed_text_stats, expand_selected_groups);

    const plan = planQueryFanout(self.io_impl, group_ids.len, req);
    recordFanoutPlan(.query, plan);
    if (plan.parallel) {
        return try queryProvisionedAcrossGroupsParallel(self, alloc, self.io_impl.?.io(), plan.width, group_ids, &shard_req, req, table_name, consistency, required_identity_generations, result_identity_generations);
    }
    if (plan.reason == .no_io) recordParallelFanoutFallback(.query);

    var shard_results = try alloc.alloc(db_mod.types.SearchResult, group_ids.len);
    var initialized: usize = 0;
    defer {
        for (shard_results[0..initialized]) |*result| result.deinit();
        alloc.free(shard_results);
    }

    for (group_ids, 0..) |group_id, i| {
        var group_req = shard_req;
        if (required_identity_generations) |generations| group_req.identity_read_generation = generations[i].?;
        shard_results[i] = try queryHostedLocal(self.resident_db, self.cache, self.replica_root_dir, self.catalog, self.requester, alloc, group_id, self.visibleRootGeneration(group_id), self.managedReadRuntimeConfig(), table_name, group_req, consistency);
        initialized += 1;
        result_identity_generations[i] = shard_results[i].identity_read_generation;
        if (required_identity_generations) |generations| {
            if (result_identity_generations[i] != generations[i]) return error.IdentityReadGenerationChanged;
        }
    }
    var merged = try mergeSearchResultsWithTableRuntimeSchema(alloc, self.catalog, table_name, req, shard_results[0..initialized], req.offset, req.limit);
    errdefer merged.deinit();
    try attachDistributedIdentityGenerations(alloc, &merged, group_ids, result_identity_generations);
    return merged;
}

fn queryHostedAcrossGroupsPhase(
    self: *HostedProvisionedTableReadSource,
    alloc: std.mem.Allocator,
    group_ids: []const u64,
    req: db_mod.types.SearchRequest,
    table_name: []const u8,
    consistency: raft_mod.ReadConsistency,
    distributed_text_stats: []const distributed_stats_mod.TextFieldStats,
    expand_selected_groups: bool,
    required_identity_generations: ?[]const ?u64,
    result_identity_generations: []?u64,
) !db_mod.types.SearchResult {
    try validateDistributedPhaseIdentityGenerations(group_ids.len, required_identity_generations, result_identity_generations);
    const shard_req = distributedSearchShardRequest(req, distributed_text_stats, expand_selected_groups);

    const plan = planQueryFanout(self.io_impl, group_ids.len, req);
    recordFanoutPlan(.query, plan);
    if (plan.parallel) {
        return try queryHostedAcrossGroupsParallel(self, alloc, self.io_impl.?.io(), plan.width, group_ids, &shard_req, req, table_name, consistency, required_identity_generations, result_identity_generations);
    }
    if (plan.reason == .no_io) recordParallelFanoutFallback(.query);

    var shard_results = try alloc.alloc(db_mod.types.SearchResult, group_ids.len);
    var initialized: usize = 0;
    defer {
        for (shard_results[0..initialized]) |*result| result.deinit();
        alloc.free(shard_results);
    }

    for (group_ids, 0..) |group_id, i| {
        var group_req = shard_req;
        if (required_identity_generations) |generations| group_req.identity_read_generation = generations[i].?;
        var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse return error.TableNotFound;
        defer route.deinit(alloc);
        shard_results[i] = switch (route) {
            .local => try queryHostedLocal(null, null, self.replica_root_dir, self.catalog, self.requester, alloc, group_id, self.visibleRootGeneration(group_id), .{ .backend_runtime = self.backend_runtime }, table_name, group_req, consistency),
            .remote => |remote| try queryRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, group_req),
        };
        initialized += 1;
        result_identity_generations[i] = shard_results[i].identity_read_generation;
        if (required_identity_generations) |generations| {
            if (result_identity_generations[i] != generations[i]) return error.IdentityReadGenerationChanged;
        }
    }
    var merged = try mergeSearchResultsWithTableRuntimeSchema(alloc, self.catalog, table_name, req, shard_results[0..initialized], req.offset, req.limit);
    errdefer merged.deinit();
    try attachDistributedIdentityGenerations(alloc, &merged, group_ids, result_identity_generations);
    return merged;
}

const ProvisionedGraphWorkerContext = struct {
    source: *ProvisionedTableReadSource,

    fn init(source: *ProvisionedTableReadSource) @This() {
        return .{ .source = source };
    }

    fn worker(self: *@This()) distributed_graph.Worker {
        return .{
            .ptr = self,
            .vtable = &.{
                .execute_graph_expand = executeProvisionedGraphExpand,
                .execute_graph_hydrate = executeProvisionedGraphHydrate,
                .execute_graph_get_edges = executeProvisionedGraphGetEdges,
                .fanout_io = provisionedGraphFanoutIo,
                .fanout_width_cap = provisionedGraphFanoutWidthCap,
            },
        };
    }
};

fn hostedGraphWorker(self: *HostedProvisionedTableReadSource) distributed_graph.Worker {
    return .{
        .ptr = self,
        .vtable = &.{
            .execute_graph_expand = executeHostedGraphExpand,
            .execute_graph_hydrate = executeHostedGraphHydrate,
            .execute_graph_get_edges = executeHostedGraphGetEdges,
            .fanout_io = hostedGraphFanoutIo,
            .fanout_width_cap = hostedGraphFanoutWidthCap,
        },
    };
}

fn provisionedGraphFanoutIo(ptr: *anyopaque) ?std.Io {
    const ctx: *ProvisionedGraphWorkerContext = @ptrCast(@alignCast(ptr));
    const io_impl = ctx.source.io_impl orelse return null;
    return io_impl.io();
}

fn provisionedGraphFanoutWidthCap(ptr: *anyopaque) usize {
    const ctx: *ProvisionedGraphWorkerContext = @ptrCast(@alignCast(ptr));
    const io_impl = ctx.source.io_impl orelse return 1;
    return ioAsyncLimitCap(io_impl);
}

fn hostedGraphFanoutIo(ptr: *anyopaque) ?std.Io {
    const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
    const io_impl = self.io_impl orelse return null;
    return io_impl.io();
}

fn hostedGraphFanoutWidthCap(ptr: *anyopaque) usize {
    const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
    const io_impl = self.io_impl orelse return 1;
    return ioAsyncLimitCap(io_impl);
}

fn executeProvisionedGraphExpand(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphExpandRequest,
    consistency: raft_mod.ReadConsistency,
) !distributed_graph.GraphExpandResponse {
    const ctx: *ProvisionedGraphWorkerContext = @ptrCast(@alignCast(ptr));
    var attempt: usize = 0;
    while (attempt < ProvisionedTableReadSource.topology_read_attempt_limit) : (attempt += 1) {
        return executeProvisionedGraphExpandAttempt(ptr, alloc, group_id, table_name, req, consistency) catch |err| switch (err) {
            error.ResidentDbRetryRequired => {
                try ctx.source.prepareResidentGroupsForReadRetry(alloc, table_name, &.{group_id});
                if (attempt + 1 < ProvisionedTableReadSource.topology_read_attempt_limit) continue;
                return error.StorageReadTemporarilyUnavailable;
            },
            else => return err,
        };
    }
    unreachable;
}

fn executeProvisionedGraphExpandAttempt(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphExpandRequest,
    consistency: raft_mod.ReadConsistency,
) !distributed_graph.GraphExpandResponse {
    const ctx: *ProvisionedGraphWorkerContext = @ptrCast(@alignCast(ptr));
    const self = ctx.source;
    var gate_request: ?ProvisionedConsistencyRequest = null;
    var gate_req: db_mod.types.SearchRequest = undefined;
    if (req.frontier.len > 0) {
        gate_req = try distributed_graph.frontierItemToSearchRequest(alloc, req, req.frontier[0]);
        defer distributed_graph.freeExpandSearchRequest(alloc, gate_req);
        gate_request = .{ .search = gate_req };
    }
    // A consistency wait may depend on Raft apply, while apply takes the
    // table's exclusive operation admission. The shared helper completes the
    // wait first, then admits and revalidates the caller's topology stamp.
    var read_activity = try self.prepareKnownGroupRead(alloc, group_id, table_name, gate_request, consistency, .general, req.topology_epoch);
    defer if (read_activity) |*activity| activity.deinit();
    var db_owner = try provisionedLocalQueryDbOwner(
        self.resident_db,
        self.cache,
        self.replica_root_dir,
        self.catalog,
        alloc,
        group_id,
        self.visibleRootGeneration(group_id),
        self.backend_runtime,
        table_name,
        read_activity != null,
    );
    defer db_owner.deinit();
    const expansions = try alloc.alloc(distributed_graph.GraphExpansion, req.frontier.len);
    var initialized: usize = 0;
    errdefer {
        for (expansions[0..initialized]) |*expansion| expansion.deinit(alloc);
        alloc.free(expansions);
    }

    for (req.frontier, 0..) |item, i| {
        const search_req = try distributed_graph.frontierItemToSearchRequest(alloc, req, item);
        defer distributed_graph.freeExpandSearchRequest(alloc, search_req);

        const frontier_key = try alloc.dupe(u8, item.key);
        errdefer alloc.free(frontier_key);
        var graph_result = graph_result_blk: {
            var result = try db_owner.db().search(alloc, search_req);
            defer result.deinit();
            var filtered = if (result.graph_results.len > 0)
                try distributed_graph.filterGraphSearchResult(alloc, table_name, result.graph_results[0], req.exclude_nodes, req.exclude_edges)
            else
                try distributed_graph.emptyGraphSearchResult(alloc, req.name);
            for (filtered.hits) |*hit| hit.deinit(alloc);
            if (filtered.hits.len > 0) alloc.free(filtered.hits);
            filtered.hits = @constCast((&[_]db_mod.types.SearchHit{})[0..]);
            break :graph_result_blk filtered;
        };
        errdefer graph_result.deinit(alloc);
        expansions[i] = .{
            .frontier_id = item.id,
            .frontier_key = frontier_key,
            .graph_result = graph_result,
        };
        initialized += 1;
    }
    return .{ .expansions = expansions };
}

fn executeProvisionedGraphHydrate(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphHydrateRequest,
    consistency: raft_mod.ReadConsistency,
) !distributed_graph.GraphHydrateResponse {
    const ctx: *ProvisionedGraphWorkerContext = @ptrCast(@alignCast(ptr));
    var attempt: usize = 0;
    while (attempt < ProvisionedTableReadSource.topology_read_attempt_limit) : (attempt += 1) {
        return executeProvisionedGraphHydrateAttempt(ptr, alloc, group_id, table_name, req, consistency) catch |err| switch (err) {
            error.ResidentDbRetryRequired => {
                try ctx.source.prepareResidentGroupsForReadRetry(alloc, table_name, &.{group_id});
                if (attempt + 1 < ProvisionedTableReadSource.topology_read_attempt_limit) continue;
                return error.StorageReadTemporarilyUnavailable;
            },
            else => return err,
        };
    }
    unreachable;
}

fn executeProvisionedGraphHydrateAttempt(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphHydrateRequest,
    consistency: raft_mod.ReadConsistency,
) !distributed_graph.GraphHydrateResponse {
    const ctx: *ProvisionedGraphWorkerContext = @ptrCast(@alignCast(ptr));
    const self = ctx.source;
    const search_req = graphHydrateSearchRequest(req);
    var read_activity = try self.prepareKnownGroupRead(alloc, group_id, table_name, .{ .search = search_req }, consistency, .general, req.topology_epoch);
    defer if (read_activity) |*activity| activity.deinit();
    var db_owner = try provisionedLocalQueryDbOwner(
        self.resident_db,
        self.cache,
        self.replica_root_dir,
        self.catalog,
        alloc,
        group_id,
        self.visibleRootGeneration(group_id),
        self.backend_runtime,
        table_name,
        read_activity != null,
    );
    defer db_owner.deinit();
    try validateGraphHydrateResolvedDocFilterForDb(req, db_owner.db());

    return try graphHydrateOnPreparedDb(alloc, db_owner.db(), req, search_req);
}

fn executeHostedGraphExpand(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphExpandRequest,
    consistency: raft_mod.ReadConsistency,
) !distributed_graph.GraphExpandResponse {
    return (try HostedProvisionedTableReadSource.graphExpandGroupLocal(ptr, alloc, group_id, table_name, req, consistency)) orelse return error.TableNotFound;
}

fn executeHostedGraphHydrate(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphHydrateRequest,
    consistency: raft_mod.ReadConsistency,
) !distributed_graph.GraphHydrateResponse {
    const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
    var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse return error.TableNotFound;
    defer route.deinit(alloc);

    return switch (route) {
        .local => blk: {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);
            const identity_namespace = try requireTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);
            var db = try db_mod.DB.open(alloc, path, .{
                .backend_runtime = self.backend_runtime,
                .identity_namespace = identity_namespace,
                .prefer_existing_identity_namespace = true,
            });
            defer db.close();
            try validateOpenedProvisionedDbIdentityNamespace(&db, identity_namespace);
            try validateGraphHydrateResolvedDocFilterForDb(req, &db);

            const reads = raft_mod.FeatureDBReads.init(group_id, self.requester);
            break :blk try graphHydrateOnOpenDb(alloc, reads, &db, req, consistency, false);
        },
        .remote => |remote| blk: {
            if (req.resolved_doc_filter != null) {
                const ctx = req.resolved_doc_filter_wire_context orelse return error.UnsupportedQueryRequest;
                try table_catalog.validateResolvedDocFilterContextForGroups(
                    alloc,
                    self.catalog,
                    table_name,
                    &.{group_id},
                    ctx.namespace.table_id,
                    ctx.namespace.shard_id,
                    ctx.namespace.range_id,
                );
            }
            break :blk try graphHydrateRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, req);
        },
    };
}

fn executeProvisionedGraphGetEdges(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphEdgesRequest,
    consistency: raft_mod.ReadConsistency,
) anyerror!distributed_graph.GraphEdgesResponse {
    const ctx: *ProvisionedGraphWorkerContext = @ptrCast(@alignCast(ptr));
    var attempt: usize = 0;
    while (attempt < ProvisionedTableReadSource.topology_read_attempt_limit) : (attempt += 1) {
        return executeProvisionedGraphGetEdgesAttempt(ptr, alloc, group_id, table_name, req, consistency) catch |err| switch (err) {
            error.ResidentDbRetryRequired => {
                try ctx.source.prepareResidentGroupsForReadRetry(alloc, table_name, &.{group_id});
                if (attempt + 1 < ProvisionedTableReadSource.topology_read_attempt_limit) continue;
                return error.StorageReadTemporarilyUnavailable;
            },
            else => return err,
        };
    }
    unreachable;
}

fn executeProvisionedGraphGetEdgesAttempt(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphEdgesRequest,
    consistency: raft_mod.ReadConsistency,
) anyerror!distributed_graph.GraphEdgesResponse {
    const ctx: *ProvisionedGraphWorkerContext = @ptrCast(@alignCast(ptr));
    const self = ctx.source;
    try distributed_graph.validateGraphEdgesTensorAccessPath(alloc, req);
    var read_activity = try self.prepareKnownGroupRead(alloc, group_id, table_name, .{ .lookup = .{ .key = req.key, .opts = .{} } }, consistency, .general, req.topology_epoch);
    defer if (read_activity) |*activity| activity.deinit();
    var db_owner = try provisionedLocalQueryDbOwner(
        self.resident_db,
        self.cache,
        self.replica_root_dir,
        self.catalog,
        alloc,
        group_id,
        self.visibleRootGeneration(group_id),
        self.backend_runtime,
        table_name,
        read_activity != null,
    );
    defer db_owner.deinit();
    _ = try currentIdentityReadGenerationForDb(req.identity_read_generation, db_owner.db());

    const graph_entry = db_owner.db().core.graphIndex(req.index_name) orelse return error.IndexNotFound;
    return .{ .edges = try graph_entry.index.getEdgesByTypes(alloc, req.key, req.edge_types, req.direction) };
}

fn executeHostedGraphGetEdges(
    ptr: *anyopaque,
    alloc: std.mem.Allocator,
    group_id: u64,
    table_name: []const u8,
    req: distributed_graph.GraphEdgesRequest,
    consistency: raft_mod.ReadConsistency,
) anyerror!distributed_graph.GraphEdgesResponse {
    const self: *HostedProvisionedTableReadSource = @ptrCast(@alignCast(ptr));
    var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse return error.TableNotFound;
    defer route.deinit(alloc);

    return switch (route) {
        .local => graphGetEdgesLocal(alloc, self.replica_root_dir, self.catalog, self.requester, group_id, self.visibleRootGeneration(group_id), self.backend_runtime, table_name, req, consistency),
        .remote => |remote| try graphEdgesRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, req),
    };
}

fn graphGetEdgesLocal(
    alloc: std.mem.Allocator,
    replica_root_dir: []const u8,
    catalog: table_catalog.CatalogSource,
    requester: raft_mod.ReadableLeaseRequester,
    group_id: u64,
    lsm_root_generation: u64,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime,
    table_name: []const u8,
    req: distributed_graph.GraphEdgesRequest,
    consistency: raft_mod.ReadConsistency,
) anyerror!distributed_graph.GraphEdgesResponse {
    try table_catalog.validateTopologyEpoch(alloc, catalog, table_name, req.topology_epoch);
    try distributed_graph.validateGraphEdgesTensorAccessPath(alloc, req);

    const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, replica_root_dir, group_id);
    defer alloc.free(path);
    var db = try openProvisionedQueryDbForTableWithRuntime(alloc, path, catalog, table_name, group_id, lsm_root_generation, backend_runtime);
    defer db.close();
    _ = try currentIdentityReadGenerationForDb(req.identity_read_generation, &db);

    const reads = raft_mod.FeatureDBReads.init(group_id, requester);
    try reads.reads.prepareLookupWithConsistency(group_id, req.key, .{}, consistency);

    const graph_entry = db.core.graphIndex(req.index_name) orelse return error.IndexNotFound;
    const edges = try graph_entry.index.getEdgesByTypes(alloc, req.key, req.edge_types, req.direction);
    return .{ .edges = edges };
}

fn lookupLocal(
    replica_root_dir: []const u8,
    requester: raft_mod.ReadableLeaseRequester,
    alloc: std.mem.Allocator,
    group_id: u64,
    key: []const u8,
    opts: db_mod.types.LookupOptions,
    consistency: raft_mod.ReadConsistency,
) !?LookupResponse {
    try checkLookupOptionsActive(opts);
    const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, replica_root_dir, group_id);
    defer alloc.free(path);
    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try checkLookupOptionsActive(opts);

    var reads = raft_mod.FeatureDBReads.init(group_id, requester);
    var result = (try reads.lookupWithConsistency(alloc, &db, key, opts, consistency)) orelse return null;
    defer result.deinit(alloc);
    try checkLookupOptionsActive(opts);
    const version = try db.getTimestamp(alloc, key);
    try checkLookupOptionsActive(opts);
    return try controlledLookupResponseAlloc(alloc, result.json, version, opts);
}

fn lookupProvisionedLocal(
    resident_db: ?ResidentDbSource,
    cache: ?*ProvisionedTableReadCache,
    replica_root_dir: []const u8,
    catalog: table_catalog.CatalogSource,
    requester: raft_mod.ReadableLeaseRequester,
    alloc: std.mem.Allocator,
    group_id: u64,
    lsm_root_generation: u64,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime,
    table_name: []const u8,
    key: []const u8,
    opts: db_mod.types.LookupOptions,
    consistency: raft_mod.ReadConsistency,
) !?LookupResponse {
    try checkLookupOptionsActive(opts);
    // Point lookups need only the primary document store. Prefer the existing
    // generation-matched writer/apply DB so a lookup does not open and retire a
    // second full index catalog over a path that is concurrently compacting.
    // Writer-backed sources return ResidentDbRetryRequired when publication is
    // needed; their caller releases admission, prepares the writer, and reruns
    // routing before reaching this function again. A null lease is reserved for
    // query-only runtimes, which use the cache.
    if (resident_db) |source| {
        if (try source.leaseGroup(alloc, table_name, group_id, lsm_root_generation, .{ .read_activity_held = true })) |lease_value| {
            var lease = lease_value;
            defer lease.release(alloc);
            try checkLookupOptionsActive(opts);
            try validateProvisionedDbIdentityNamespace(alloc, catalog, table_name, group_id, lease.db);
            try checkLookupOptionsActive(opts);

            var reads = raft_mod.FeatureDBReads.init(group_id, requester);
            var result = (try reads.lookupWithConsistency(alloc, lease.db, key, opts, consistency)) orelse return null;
            defer result.deinit(alloc);
            const version = try lease.db.getTimestamp(alloc, key);
            try checkLookupOptionsActive(opts);
            return try controlledLookupResponseAlloc(alloc, result.json, version, opts);
        }
    }

    const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, replica_root_dir, group_id);
    defer alloc.free(path);
    if (cache) |cached| {
        var lease = try cached.getOrOpen(path, catalog, group_id, lsm_root_generation, table_name);
        defer lease.release();
        try checkLookupOptionsActive(opts);
        try validateProvisionedDbIdentityNamespace(alloc, catalog, table_name, group_id, lease.db);
        try checkLookupOptionsActive(opts);

        var reads = raft_mod.FeatureDBReads.init(group_id, requester);
        var result = (try reads.lookupWithConsistency(alloc, lease.db, key, opts, consistency)) orelse return null;
        defer result.deinit(alloc);
        const version = try lease.db.getTimestamp(alloc, key);
        try checkLookupOptionsActive(opts);
        return try controlledLookupResponseAlloc(alloc, result.json, version, opts);
    }

    var db = try openProvisionedLookupDbForTable(
        alloc,
        path,
        null,
        lsm_root_generation,
        null,
        backend_runtime,
        try requireTableIdentityNamespaceForGroup(alloc, catalog, table_name, group_id),
    );
    defer db.close();
    try checkLookupOptionsActive(opts);

    var reads = raft_mod.FeatureDBReads.init(group_id, requester);
    var result = (try reads.lookupWithConsistency(alloc, &db, key, opts, consistency)) orelse return null;
    defer result.deinit(alloc);
    const version = try db.getTimestamp(alloc, key);
    try checkLookupOptionsActive(opts);
    return try controlledLookupResponseAlloc(alloc, result.json, version, opts);
}

fn lookupHostedLocal(
    replica_root_dir: []const u8,
    requester: raft_mod.ReadableLeaseRequester,
    alloc: std.mem.Allocator,
    group_id: u64,
    key: []const u8,
    opts: db_mod.types.LookupOptions,
    consistency: raft_mod.ReadConsistency,
) !?LookupResponse {
    return lookupLocal(replica_root_dir, requester, alloc, group_id, key, opts, consistency) catch |err| switch (err) {
        error.NotLeader => if (consistency == .stale) err else try lookupLocal(replica_root_dir, requester, alloc, group_id, key, opts, .stale),
        else => err,
    };
}

fn lookupProvisionedHostedLocal(
    resident_db: ?ResidentDbSource,
    cache: ?*ProvisionedTableReadCache,
    replica_root_dir: []const u8,
    catalog: table_catalog.CatalogSource,
    requester: raft_mod.ReadableLeaseRequester,
    alloc: std.mem.Allocator,
    group_id: u64,
    lsm_root_generation: u64,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime,
    table_name: []const u8,
    key: []const u8,
    opts: db_mod.types.LookupOptions,
    consistency: raft_mod.ReadConsistency,
) !?LookupResponse {
    return lookupProvisionedLocal(resident_db, cache, replica_root_dir, catalog, requester, alloc, group_id, lsm_root_generation, backend_runtime, table_name, key, opts, consistency) catch |err| switch (err) {
        error.NotLeader => if (consistency == .stale) err else try lookupProvisionedLocal(resident_db, cache, replica_root_dir, catalog, requester, alloc, group_id, lsm_root_generation, backend_runtime, table_name, key, opts, .stale),
        else => err,
    };
}

