fn collectHostedAggregationBackgroundTextStats(
    self: *HostedProvisionedTableReadSource,
    alloc: std.mem.Allocator,
    group_ids: []const u64,
    table_name: []const u8,
    req: db_mod.types.SearchRequest,
    hits: []const db_mod.types.SearchHit,
    text_analysis: *const introducer_mod.TextAnalysisConfig,
    consistency: raft_mod.ReadConsistency,
    required_identity_generations: ?[]const ?u64,
) ![]const db_mod.aggregations.DistributedBackgroundTextStats {
    if (group_ids.len <= 1 or req.aggregations_json.len == 0) return &.{};
    try tableReadsValidateDocIdentityReadyForMultiGroup(alloc, self.catalog, table_name, group_ids.len);
    try validateRequiredIdentityGenerations(group_ids.len, required_identity_generations);
    const requests = try query_api.parseAggregationRequestsJson(alloc, req.aggregations_json);
    defer query_api.freeAggregationRequests(alloc, requests);
    const field_requests = try collectSignificantTermsBackgroundFieldRequests(alloc, requests, hits, text_analysis);
    defer {
        for (field_requests) |*item| item.deinit(alloc);
        if (field_requests.len > 0) alloc.free(field_requests);
    }
    if (field_requests.len == 0) return &.{};
    const shard_stats = try alloc.alloc([]const db_mod.aggregations.DistributedBackgroundTextStats, group_ids.len);
    var initialized: usize = 0;
    defer {
        for (shard_stats[0..initialized]) |item| db_mod.aggregations.deinitDistributedBackgroundTextStats(alloc, item);
        alloc.free(shard_stats);
    }
    for (group_ids, 0..) |group_id, i| {
        var group_req = req;
        if (required_identity_generations) |generations| group_req.identity_read_generation = generations[i].?;
        const body = try encodeBackgroundTextStatsRequestForSearchRequest(alloc, field_requests, group_req);
        defer alloc.free(body);
        var route = (try table_router.resolveGroupRoute(alloc, self.catalog, self.router, group_id, routePolicyForConsistency(consistency))) orelse return error.TableNotFound;
        defer route.deinit(alloc);
        var response = switch (route) {
            .local => (try collectProvisionedHostedLocalTextStats(null, null, self.replica_root_dir, self.catalog, alloc, group_id, self.visibleRootGeneration(group_id), self.backend_runtime, table_name, body, false)) orelse return error.TableNotFound,
            .remote => |remote| (try textStatsRemote(self.internalExecutor(), alloc, remote.base_uri, group_id, table_name, body, group_req)) orelse return error.TableNotFound,
        };
        defer response.deinit(alloc);
        shard_stats[i] = try parseBackgroundTextStatsResponse(alloc, response.json);
        initialized += 1;
    }
    return try mergeDistributedBackgroundTextStats(alloc, shard_stats[0..initialized]);
}

fn applyQueryPostProcessing(
    alloc: std.mem.Allocator,
    req: db_mod.types.SearchRequest,
    result: *db_mod.types.SearchResult,
    meta: *query_api.QueryResponseMeta,
    antfly_provider: ?managed_embedder.AntflyProvider,
    secret_store: ?*common_secrets.FileStore,
) !void {
    if (req.reranker == null or result.hits.len == 0) return;
    try applyReranker(alloc, req, result, meta, antfly_provider, secret_store);
}

fn applyReranker(
    alloc: std.mem.Allocator,
    req: db_mod.types.SearchRequest,
    result: *db_mod.types.SearchResult,
    meta: *query_api.QueryResponseMeta,
    antfly_provider: ?managed_embedder.AntflyProvider,
    secret_store: ?*common_secrets.FileStore,
) !void {
    const cfg = req.reranker orelse return;
    if (req.reranker_query_text.len == 0) return error.UnsupportedQueryRequest;

    const doc_template = if (cfg.template.len > 0)
        try alloc.dupe(u8, cfg.template)
    else
        try std.fmt.allocPrint(alloc, "{{{{{s}}}}}", .{cfg.field});
    defer alloc.free(doc_template);

    const rerank_count: usize = if (cfg.top_n) |top_n|
        @min(result.hits.len, top_n)
    else
        result.hits.len;

    const documents = try alloc.alloc([]const u8, rerank_count);
    defer alloc.free(documents);
    var initialized_docs: usize = 0;
    defer {
        for (documents[0..initialized_docs]) |document| alloc.free(document);
    }

    for (result.hits[0..rerank_count], 0..) |hit, i| {
        documents[i] = try renderRerankerDocument(alloc, doc_template, hit);
        initialized_docs += 1;
    }

    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    var http = httpx.Client.initWithConfig(alloc, io_impl.io(), .{ .keep_alive = false });
    defer http.deinit();

    const rerank_start_ns = platform_time.monotonicNs();
    const scores = reranking_runtime.rerankDocumentsWithOptions(
        alloc,
        &http,
        cfg,
        .{ .antfly_provider = antfly_provider, .secret_store = secret_store },
        req.reranker_query_text,
        documents,
    ) catch |err| switch (err) {
        error.InvalidRerankerConfig, error.UnsupportedRerankerProvider => return error.InvalidQueryRequest,
        else => return err,
    };
    defer alloc.free(scores);
    if (scores.len != rerank_count) return error.InvalidRerankerResponse;

    for (result.hits[0..rerank_count], 0..) |*hit, i| {
        hit.score = scores[i];
    }
    std.sort.pdq(db_mod.types.SearchHit, result.hits[0..rerank_count], {}, struct {
        fn lessThan(_: void, a: db_mod.types.SearchHit, b: db_mod.types.SearchHit) bool {
            const a_score = a.score orelse 0;
            const b_score = b.score orelse 0;
            if (a_score != b_score) return a_score > b_score;
            return std.mem.order(u8, a.id, b.id) == .lt;
        }
    }.lessThan);

    if (cfg.top_n) |top_n| {
        try truncateSearchHits(alloc, result, @min(top_n, result.hits.len));
        result.total_hits = @min(result.total_hits, top_n);
    }

    meta.reranker = .{
        .model = cfg.model,
        .documents_reranked = @intCast(scores.len),
        .duration_ms = @intCast(@divTrunc(platform_time.monotonicNs() - rerank_start_ns, std.time.ns_per_ms)),
    };
}

fn renderRerankerDocument(
    alloc: std.mem.Allocator,
    doc_template: []const u8,
    hit: db_mod.types.SearchHit,
) ![]const u8 {
    const raw = hit.stored_data orelse return try alloc.dupe(u8, "");
    return template_mod.renderDocument(alloc, doc_template, raw) catch try alloc.dupe(u8, "");
}

fn truncateSearchHits(
    alloc: std.mem.Allocator,
    result: *db_mod.types.SearchResult,
    keep_len: usize,
) !void {
    if (keep_len >= result.hits.len) return;
    const old_hits = result.hits;
    var kept = try alloc.alloc(db_mod.types.SearchHit, keep_len);
    for (old_hits[0..keep_len], 0..) |hit, i| {
        kept[i] = hit;
    }
    for (old_hits[keep_len..]) |*hit| hit.deinit(alloc);
    alloc.free(old_hits);
    result.hits = kept;
}

fn lookupRemote(
    executor: http_common.RequestExecutor,
    alloc: std.mem.Allocator,
    base_uri: []const u8,
    group_id: u64,
    table_name: []const u8,
    key: []const u8,
    opts: db_mod.types.LookupOptions,
    consistency: raft_mod.ReadConsistency,
) !?LookupResponse {
    try checkLookupOptionsActive(opts);
    var client = http_client.ApiHttpClient.init(alloc, executor);
    const fields = try encodeLookupFields(alloc, opts);
    defer if (fields) |value| alloc.free(value);
    const timeout_ms = try lookupRemainingTimeoutMs(opts);
    var request_cancellation = if (opts.cancellation) |token| http_common.RequestCancellation.fromToken(token) else http_common.RequestCancellation{};
    const cancellation: ?*const http_common.RequestCancellation = if (opts.cancellation != null) &request_cancellation else null;
    const read_consistency = switch (consistency) {
        .stale => "stale",
        .leader_lease => "leader_lease",
        .read_index => "read_index",
    };
    var result = try client.fetchGroupLookupWithControl(
        base_uri,
        group_id,
        table_name,
        key,
        fields,
        read_consistency,
        timeout_ms,
        cancellation,
    );
    defer result.deinit(alloc);
    try checkLookupOptionsActive(opts);
    return try controlledLookupResponseAlloc(
        alloc,
        result.body,
        if (result.version) |version| try std.fmt.parseUnsigned(u64, version, 10) else 0,
        opts,
    );
}

const RemoteDocumentArtifactManifest = struct {
    const ChildRange = struct {
        range_id: []const u8 = "",
        range_kind: []const u8 = "",
        artifact_name: []const u8 = "",
        split_boundary: []const u8 = "",
        placement: []const u8 = "",
        owner_group_id: ?u64 = null,
        placement_generation: ?u64 = null,
        route_status: ?[]const u8 = null,
        split_eligible: ?bool = null,
        start_key: []const u8 = "",
        end_key_exclusive: []const u8 = "",
        last_key: []const u8 = "",
        child_count: usize = 0,
        text_bytes: ?usize = null,
    };

    document_id: []const u8,
    artifact_name: []const u8,
    artifact_id: []const u8,
    manifest_version: u64 = 0,
    generation: u64 = 0,
    source_url: []const u8 = "",
    source_fingerprint: []const u8 = "",
    content_type: []const u8 = "",
    route_type: []const u8 = "",
    unsupported_reason: ?[]const u8 = null,
    unit_count: usize = 0,
    chunk_count: usize = 0,
    ocr_attempted_count: usize = 0,
    ocr_selected_count: usize = 0,
    ocr_retained_embedded_count: usize = 0,
    ocr_failed_count: usize = 0,
    ocr_failed_page_numbers: []const i64 = &.{},
    ocr_failed_pages_truncated: bool = false,
    child_ranges: []const ChildRange = &.{},
    child_range_count: usize = 0,
    merge_status: []const u8 = "",
    merge_from_generation: u64 = 0,
    merge_to_generation: u64 = 0,
    merge_operation_granularity: []const u8 = "",
    merge_operation_count: usize = 0,
    last_error_code: ?[]const u8 = null,
    last_error_message: ?[]const u8 = null,
    manifest_json: []const u8,
    state_json: ?[]const u8 = null,
};

const RemoteDocumentArtifactManifests = struct {
    document_id: []const u8,
    artifacts: []const RemoteDocumentArtifactManifest,
};

fn remoteDocumentArtifactChildRangesAlloc(alloc: std.mem.Allocator, remote: []const RemoteDocumentArtifactManifest.ChildRange) ![]db_mod.types.DocumentArtifactChildRange {
    const child_ranges = try alloc.alloc(db_mod.types.DocumentArtifactChildRange, remote.len);
    var initialized_child_ranges: usize = 0;
    errdefer {
        for (child_ranges[0..initialized_child_ranges]) |*child_range| child_range.deinit(alloc);
        if (child_ranges.len > 0) alloc.free(child_ranges);
    }
    for (remote, child_ranges) |remote_range, *out| {
        out.* = .{
            .range_id = try alloc.dupe(u8, remote_range.range_id),
            .range_kind = try alloc.dupe(u8, remote_range.range_kind),
            .artifact_name = try alloc.dupe(u8, remote_range.artifact_name),
            .split_boundary = try alloc.dupe(u8, remote_range.split_boundary),
            .placement = try alloc.dupe(u8, remote_range.placement),
            .owner_group_id = remote_range.owner_group_id,
            .placement_generation = remote_range.placement_generation,
            .route_status = if (remote_range.route_status) |value| try alloc.dupe(u8, value) else null,
            .split_eligible = remote_range.split_eligible,
            .start_key = try alloc.dupe(u8, remote_range.start_key),
            .end_key_exclusive = try alloc.dupe(u8, remote_range.end_key_exclusive),
            .last_key = try alloc.dupe(u8, remote_range.last_key),
            .child_count = remote_range.child_count,
            .text_bytes = remote_range.text_bytes,
        };
        initialized_child_ranges += 1;
    }
    return child_ranges;
}

fn remoteDocumentArtifactManifestAlloc(alloc: std.mem.Allocator, remote: RemoteDocumentArtifactManifest) !db_mod.types.DocumentArtifactManifest {
    const child_ranges = try remoteDocumentArtifactChildRangesAlloc(alloc, remote.child_ranges);
    errdefer {
        for (child_ranges) |*child_range| child_range.deinit(alloc);
        if (child_ranges.len > 0) alloc.free(child_ranges);
    }

    const document_id = try alloc.dupe(u8, remote.document_id);
    errdefer alloc.free(document_id);
    const artifact_name = try alloc.dupe(u8, remote.artifact_name);
    errdefer alloc.free(artifact_name);
    const artifact_id = try alloc.dupe(u8, remote.artifact_id);
    errdefer alloc.free(artifact_id);
    const manifest_json = try alloc.dupe(u8, remote.manifest_json);
    errdefer alloc.free(manifest_json);
    const state_json = if (remote.state_json) |value| try alloc.dupe(u8, value) else null;
    errdefer if (state_json) |value| alloc.free(value);
    const source_url: []u8 = if (remote.source_url.len > 0) try alloc.dupe(u8, remote.source_url) else @constCast("");
    errdefer if (source_url.len > 0) alloc.free(source_url);
    const source_fingerprint: []u8 = if (remote.source_fingerprint.len > 0) try alloc.dupe(u8, remote.source_fingerprint) else @constCast("");
    errdefer if (source_fingerprint.len > 0) alloc.free(source_fingerprint);
    const content_type: []u8 = if (remote.content_type.len > 0) try alloc.dupe(u8, remote.content_type) else @constCast("");
    errdefer if (content_type.len > 0) alloc.free(content_type);
    const route_type: []u8 = if (remote.route_type.len > 0) try alloc.dupe(u8, remote.route_type) else @constCast("");
    errdefer if (route_type.len > 0) alloc.free(route_type);
    const unsupported_reason = if (remote.unsupported_reason) |value| try alloc.dupe(u8, value) else null;
    errdefer if (unsupported_reason) |value| alloc.free(value);
    const merge_status: []u8 = if (remote.merge_status.len > 0) try alloc.dupe(u8, remote.merge_status) else @constCast("");
    errdefer if (merge_status.len > 0) alloc.free(merge_status);
    const merge_operation_granularity: []u8 = if (remote.merge_operation_granularity.len > 0) try alloc.dupe(u8, remote.merge_operation_granularity) else @constCast("");
    errdefer if (merge_operation_granularity.len > 0) alloc.free(merge_operation_granularity);
    const last_error_code = if (remote.last_error_code) |value| try alloc.dupe(u8, value) else null;
    errdefer if (last_error_code) |value| alloc.free(value);
    const last_error_message = if (remote.last_error_message) |value| try alloc.dupe(u8, value) else null;
    errdefer if (last_error_message) |value| alloc.free(value);
    const ocr_failed_page_numbers: []i64 = if (remote.ocr_failed_page_numbers.len > 0)
        try alloc.dupe(i64, remote.ocr_failed_page_numbers)
    else
        @constCast(&.{});
    errdefer if (ocr_failed_page_numbers.len > 0) alloc.free(ocr_failed_page_numbers);

    return .{
        .document_id = document_id,
        .artifact_name = artifact_name,
        .artifact_id = artifact_id,
        .manifest_json = manifest_json,
        .state_json = state_json,
        .manifest_version = remote.manifest_version,
        .generation = remote.generation,
        .source_url = source_url,
        .source_fingerprint = source_fingerprint,
        .content_type = content_type,
        .route_type = route_type,
        .unsupported_reason = unsupported_reason,
        .unit_count = remote.unit_count,
        .chunk_count = remote.chunk_count,
        .ocr_attempted_count = remote.ocr_attempted_count,
        .ocr_selected_count = remote.ocr_selected_count,
        .ocr_retained_embedded_count = remote.ocr_retained_embedded_count,
        .ocr_failed_count = remote.ocr_failed_count,
        .ocr_failed_page_numbers = ocr_failed_page_numbers,
        .ocr_failed_pages_truncated = remote.ocr_failed_pages_truncated,
        .child_ranges = child_ranges,
        .child_range_count = if (remote.child_range_count > 0) remote.child_range_count else child_ranges.len,
        .merge_status = merge_status,
        .merge_from_generation = remote.merge_from_generation,
        .merge_to_generation = remote.merge_to_generation,
        .merge_operation_granularity = merge_operation_granularity,
        .merge_operation_count = remote.merge_operation_count,
        .last_error_code = last_error_code,
        .last_error_message = last_error_message,
    };
}

fn parseRemoteDocumentArtifactManifest(alloc: std.mem.Allocator, body: []const u8) !db_mod.types.DocumentArtifactManifest {
    var parsed = try std.json.parseFromSlice(RemoteDocumentArtifactManifest, alloc, body, .{});
    defer parsed.deinit();

    return try remoteDocumentArtifactManifestAlloc(alloc, parsed.value);
}

fn parseRemoteDocumentArtifactManifests(alloc: std.mem.Allocator, body: []const u8) !db_mod.types.DocumentArtifactManifestList {
    var parsed = try std.json.parseFromSlice(RemoteDocumentArtifactManifests, alloc, body, .{});
    defer parsed.deinit();

    var artifacts = try alloc.alloc(db_mod.types.DocumentArtifactManifest, parsed.value.artifacts.len);
    errdefer alloc.free(artifacts);
    var initialized: usize = 0;
    errdefer {
        for (artifacts[0..initialized]) |*artifact| artifact.deinit(alloc);
    }
    for (parsed.value.artifacts, artifacts) |remote, *out| {
        out.* = try remoteDocumentArtifactManifestAlloc(alloc, remote);
        initialized += 1;
    }

    return .{
        .document_id = try alloc.dupe(u8, parsed.value.document_id),
        .artifacts = artifacts,
    };
}

