fn joinUnmatchedRemote(
    executor: http_common.RequestExecutor,
    alloc: std.mem.Allocator,
    base_uri: []const u8,
    group_id: u64,
    table_name: []const u8,
    body: []const u8,
    timeout_ms: ?u32,
) !?query_api.QueryResponse {
