            .limit = 8,
            .offset = 1,
            .profile = true,
            .include_stored = false,
            .search_effort = 0.5,
            .distance_over = 0.1,
            .distance_under = 0.9,
            .return_mode = .parent_with_chunks,
            .max_chunks_per_parent = 2,
            .hierarchy_omit_implicit_source_ancestor_document = true,
            .hierarchy_match_fields = @constCast((&[_][]const u8{"text"})[0..]),
