test "remote shard query phases propagate deadline and request cancellation" {
    const alloc = std.testing.allocator;

    const ExecutorState = struct {
        signal: *std.atomic.Value(bool),
        calls: usize = 0,
        algebraic_base64_header_seen: bool = false,

        fn iface(self: *@This()) http_common.RequestExecutor {
            return .{
                .ptr = self,
                .vtable = &.{ .execute = execute },
            };
        }

        fn execute(ptr: *anyopaque, _: std.mem.Allocator, req: http_common.HttpRequest) !http_common.HttpResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.calls += 1;
            try std.testing.expect(req.timeout_ms != null);
            try std.testing.expect(req.timeout_ms.? > 0);
            try std.testing.expect(req.timeout_ms.? <= 60_000);
            if (std.mem.endsWith(u8, req.uri, http_routes.Routes.algebraic_partials_suffix)) {
                try std.testing.expectEqualStrings(
                    algebraic_partials_wire.base64_v1,
                    req.header(algebraic_partials_wire.response_encoding_header) orelse return error.TestExpectedAlgebraicPartialsEncoding,
                );
                self.algebraic_base64_header_seen = true;
            }
            const cancellation = req.cancellation orelse return error.TestExpectedCancellation;
            try std.testing.expect(!cancellation.isCancelled());
            self.signal.store(true, .release);
            defer self.signal.store(false, .release);
            try std.testing.expect(cancellation.isCancelled());
            return error.Timeout;
        }
    };

    var cancelled = std.atomic.Value(bool).init(false);
    var state = ExecutorState{ .signal = &cancelled };
    const controlled_request = db_mod.types.SearchRequest{
        .execution_deadline_ns = platform_time.monotonicNs() + 60 * std.time.ns_per_s,
        .cancellation = db_mod.types.CancellationToken.fromAtomic(&cancelled),
    };
    try std.testing.expectError(error.Timeout, queryRemote(
        state.iface(),
        alloc,
        "http://remote.test",
        11,
        "docs",
        controlled_request,
    ));

    var vector_request = controlled_request;
    vector_request.index_name = "dense_idx";
    vector_request.query = .{ .dense_knn = .{ .vector = &.{ 0.25, 0.5 }, .k = 7 } };
    try std.testing.expectError(error.Timeout, queryRemote(
        state.iface(),
        alloc,
        "http://remote.test",
        11,
        "docs",
        vector_request,
    ));
    try std.testing.expectError(error.Timeout, preflightRemote(
        state.iface(),
        alloc,
        "http://remote.test",
        11,
        "docs",
        controlled_request,
        0,
    ));
    try std.testing.expectError(error.Timeout, textStatsRemote(
        state.iface(),
        alloc,
        "http://remote.test",
        11,
        "docs",
        "{}",
        controlled_request,
    ));
    try std.testing.expectError(error.Timeout, algebraicPartialsRemote(
        state.iface(),
        alloc,
        "http://remote.test",
        11,
        "docs",
        "{}",
        controlled_request,
    ));
    try std.testing.expectEqual(@as(usize, 5), state.calls);
    try std.testing.expect(state.algebraic_base64_header_seen);
}

test "remote query returns the shard-selected identity generation" {
    const alloc = std.testing.allocator;
    const Executor = struct {
        fn iface(self: *@This()) http_common.RequestExecutor {
            return .{ .ptr = self, .vtable = &.{ .execute = execute } };
        }

        fn execute(_: *anyopaque, inner_alloc: std.mem.Allocator, _: http_common.HttpRequest) !http_common.HttpResponse {
            const headers = try inner_alloc.alloc(http_common.Header, 1);
            errdefer inner_alloc.free(headers);
            const header_name = try inner_alloc.dupe(u8, query_api.QueryResponse.identity_read_generation_header);
            errdefer inner_alloc.free(header_name);
            const header_value = try inner_alloc.dupe(u8, "42");
            errdefer inner_alloc.free(header_value);
            headers[0] = .{ .name = header_name, .value = header_value };
            return .{
                .status = 200,
                .headers = headers,
                .body = try inner_alloc.dupe(u8, "{\"responses\":[{\"hits\":{\"total\":{\"value\":0,\"relation\":\"exact\"},\"hits\":[]},\"took\":0,\"status\":200,\"table\":\"docs\"}]}"),
            };
        }
    };

    var executor = Executor{};
    var result = try queryRemote(executor.iface(), alloc, "http://remote.test", 11, "docs", .{});
    defer result.deinit();
    try std.testing.expectEqual(@as(?u64, 42), result.identity_read_generation);
}

test "remote simple vector query uses vector worker route" {
    const alloc = std.testing.allocator;

    const ExecutorState = struct {
        vector_worker_calls: usize = 0,
        query_calls: usize = 0,

        fn iface(self: *@This()) http_common.RequestExecutor {
            return .{
                .ptr = self,
                .vtable = &.{ .execute = execute },
            };
        }

        fn execute(ptr: *anyopaque, alloc_inner: std.mem.Allocator, req: http_common.HttpRequest) !http_common.HttpResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqual(http_common.Method.POST, req.method);
            const generation_value: []const u8 = if (std.mem.endsWith(u8, req.uri, "/internal/v1/groups/11/tables/docs/vector-worker")) "77" else "88";
            if (std.mem.endsWith(u8, req.uri, "/internal/v1/groups/11/tables/docs/vector-worker")) {
                self.vector_worker_calls += 1;
                var envelope = try query_contract.parseAlgebraicVectorWorkerRequestEnvelopeAlloc(alloc_inner, req.body);
                defer envelope.deinit(alloc_inner);
                try std.testing.expectEqualStrings("dense_idx", envelope.index_name);
                try std.testing.expectEqual(@as(u32, 11), envelope.options.limit);
                try std.testing.expectEqual(@as(u32, 3), envelope.options.offset);
                try std.testing.expect(envelope.options.profile);
                try std.testing.expectEqual(@as(?u64, 77), envelope.options.identity_read_generation);
                try std.testing.expect(!envelope.options.include_all_fields);
                try std.testing.expect(envelope.options.defer_stored_projection);
                try std.testing.expectEqualStrings("{\"term\":{\"path\":\"/tenant\",\"value\":\"t1\"}}", envelope.options.filter_query_json);
                try std.testing.expectEqualStrings("{\"term\":{\"path\":\"/deleted\",\"value\":true}}", envelope.options.exclusion_query_json);
                try std.testing.expect(envelope.options.require_algebraic_filter_resolution);
                try std.testing.expectEqualStrings("tenant/a/", envelope.options.filter_prefix);
                try std.testing.expectEqual(@as(usize, 1), envelope.options.filter_ids.len);
                try std.testing.expectEqual(@as(u64, 42), envelope.options.filter_ids[0]);
                try std.testing.expectEqual(@as(usize, 1), envelope.options.exclude_ids.len);
                try std.testing.expectEqual(@as(u64, 7), envelope.options.exclude_ids[0]);
                try std.testing.expectEqual(@as(usize, 1), envelope.options.fields.len);
                try std.testing.expectEqualStrings("title", envelope.options.fields[0]);
                try std.testing.expectApproxEqAbs(@as(f32, 0.5), envelope.options.search_effort.?, 0.0001);
                try std.testing.expectApproxEqAbs(@as(f32, 0.9), envelope.options.distance_under.?, 0.0001);
                try std.testing.expectEqual(db_mod.types.ReturnMode.parent_with_chunks, envelope.options.return_mode);
                try std.testing.expectEqual(@as(u32, 2), envelope.options.max_chunks_per_parent);
                try std.testing.expect(envelope.native_doc_id_constraints.constraints.positive_filter);
            } else if (std.mem.endsWith(u8, req.uri, "/internal/v1/groups/11/tables/docs/query")) {
                self.query_calls += 1;
                try std.testing.expect(std.mem.indexOf(u8, req.body, "\"_filter_query_json\"") != null);
                try std.testing.expect(std.mem.indexOf(u8, req.body, "\"_identity_read_generation\":88") != null);
                try std.testing.expect(std.mem.indexOf(u8, req.body, "\"filter_query\"") == null);
            } else {
                return error.UnexpectedHttpRequest;
            }
            const headers = try alloc_inner.alloc(http_common.Header, 1);
            errdefer alloc_inner.free(headers);
            const header_name = try alloc_inner.dupe(u8, query_api.QueryResponse.identity_read_generation_header);
            errdefer alloc_inner.free(header_name);
            const header_value = try alloc_inner.dupe(u8, generation_value);
            errdefer alloc_inner.free(header_value);
            headers[0] = .{ .name = header_name, .value = header_value };
            return .{
                .status = 200,
                .headers = headers,
                .body = try alloc_inner.dupe(u8, "{\"responses\":[{\"hits\":{\"total\":{\"value\":0,\"relation\":\"exact\"},\"hits\":[]},\"took\":0,\"status\":200,\"table\":\"docs\"}]}"),
            };
        }
    };

    var state = ExecutorState{};
    var vector_result = try queryRemote(state.iface(), alloc, "http://remote.test", 11, "docs", .{
        .index_name = "dense_idx",
        .limit = 11,
        .offset = 3,
        .profile = true,
        .fields = &.{"title"},
        .filter_query_json = "{\"term\":{\"path\":\"/tenant\",\"value\":\"t1\"}}",
        .exclusion_query_json = "{\"term\":{\"path\":\"/deleted\",\"value\":true}}",
        .filter_prefix = "tenant/a/",
        .filter_ids = &.{42},
        .exclude_ids = &.{7},
        .include_all_fields = false,
        .defer_stored_projection = true,
        .search_effort = 0.5,
        .distance_under = 0.9,
        .return_mode = .parent_with_chunks,
        .max_chunks_per_parent = 2,
        .identity_read_generation = 77,
        .query = .{ .dense_knn = .{ .vector = &.{ 0.25, 0.5 }, .k = 7 } },
        .filter_doc_ids_positive = true,
        .filter_doc_ids = &.{"doc:a"},
    });
    defer vector_result.deinit();
    try std.testing.expectEqual(@as(usize, 1), state.vector_worker_calls);
    try std.testing.expectEqual(@as(usize, 0), state.query_calls);
    try std.testing.expectEqual(@as(u32, 0), vector_result.total_hits);
    try std.testing.expectEqual(db_mod.types.TotalHitsRelation.exact, vector_result.total_hits_relation);
    try std.testing.expectEqual(@as(?u64, 77), vector_result.identity_read_generation);

    var fallback_result = try queryRemote(state.iface(), alloc, "http://remote.test", 11, "docs", .{
        .index_name = "dense_idx",
        .query = .{ .dense_knn = .{ .vector = &.{ 0.25, 0.5 }, .k = 7 } },
        .filter_query_json = "{\"wildcard\":{\"/tenant\":\"*ice\"}}",
        .identity_read_generation = 88,
    });
    defer fallback_result.deinit();
    try std.testing.expectEqual(@as(usize, 1), state.vector_worker_calls);
    try std.testing.expectEqual(@as(usize, 1), state.query_calls);
    try std.testing.expectEqual(@as(u32, 0), fallback_result.total_hits);
    try std.testing.expectEqual(db_mod.types.TotalHitsRelation.exact, fallback_result.total_hits_relation);
    try std.testing.expectEqual(@as(?u64, 88), fallback_result.identity_read_generation);
}

test "remote query preserves optional should and named filter bindings" {
    const alloc = std.testing.allocator;
    const ExecutorState = struct {
        calls: usize = 0,

        fn iface(self: *@This()) http_common.RequestExecutor {
            return .{
                .ptr = self,
                .vtable = &.{ .execute = execute },
            };
        }

        fn execute(
            ptr: *anyopaque,
            alloc_inner: std.mem.Allocator,
            req: http_common.HttpRequest,
        ) !http_common.HttpResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.calls += 1;
            try std.testing.expectEqual(http_common.Method.POST, req.method);
            try std.testing.expect(std.mem.endsWith(
                u8,
                req.uri,
                "/internal/v1/groups/11/tables/docs/query",
            ));

            var parsed = try query_api.parseQueryRequest(
                alloc_inner,
                null,
                "docs",
                req.body,
            );
            defer parsed.deinit(alloc_inner);
            const full_text = parsed.req.full_text orelse return error.TestExpectedEqual;
            try std.testing.expect(full_text == .bool_query);
            try std.testing.expect(full_text.bool_query.pure_should_optional);
            try std.testing.expectEqual(@as(u32, 0), full_text.bool_query.min_should);
            try std.testing.expectEqual(@as(f32, 2.0), full_text.bool_query.boost);
            try std.testing.expect(full_text.bool_query.should[0] == .match);
            try std.testing.expectEqual(@as(f32, 3.0), full_text.bool_query.should[0].match.boost);
            try std.testing.expectEqual(@as(usize, 2), parsed.req.doc_filter_bindings.len);
            try std.testing.expectEqualStrings("tenant", parsed.req.doc_filter_bindings[0].name);
            try std.testing.expectEqualStrings("visible", parsed.req.doc_filter_bindings[1].name);
            try std.testing.expectEqualStrings("{\"ref\":\"visible\"}", parsed.req.filter_query_json);

            const headers = try alloc_inner.alloc(http_common.Header, 1);
            errdefer alloc_inner.free(headers);
            const header_name = try alloc_inner.dupe(u8, query_api.QueryResponse.identity_read_generation_header);
            errdefer alloc_inner.free(header_name);
            const header_value = try alloc_inner.dupe(u8, "42");
            errdefer alloc_inner.free(header_value);
            headers[0] = .{ .name = header_name, .value = header_value };
            return .{
                .status = 200,
                .headers = headers,
                .body = try alloc_inner.dupe(
                    u8,
                    "{\"responses\":[{\"hits\":{\"total\":{\"value\":0,\"relation\":\"exact\"},\"hits\":[]},\"took\":0,\"status\":200,\"table\":\"docs\"}]}",
                ),
            };
        }
    };

    const should_queries = [_]db_mod.types.TextQuery{
        .{ .match = .{ .field = "body", .text = "computer", .boost = 3.0 } },
    };
    const binding_defs = [_]db_mod.types.NamedDocFilterBinding{
        .{
            .name = "tenant",
            .filter_query_json = "{\"term\":{\"path\":\"/tenant\",\"value\":\"acme\"}}",
        },
        .{
            .name = "visible",
            .filter_query_json = "{\"bool\":{\"must\":[{\"ref\":\"tenant\"},{\"bool_field\":{\"field\":\"published\",\"value\":true}}]}}",
        },
    };
    var state = ExecutorState{};
    var result = try queryRemote(
        state.iface(),
        alloc,
        "http://remote.test",
        11,
        "docs",
        .{
            .full_text = .{ .bool_query = .{
                .should = should_queries[0..],
                .pure_should_optional = true,
                .boost = 2.0,
            } },
            .filter_query_json = "{\"ref\":\"visible\"}",
            .doc_filter_bindings = binding_defs[0..],
        },
    );
    defer result.deinit();
    try std.testing.expectEqual(@as(usize, 1), state.calls);
    try std.testing.expectEqual(@as(u32, 0), result.total_hits);
}

